window.ThreeKGProfile = {"version": "Profile R02.1 + Sortlist content and portfolio revival review 2026-10-28", "categories": {"studio": "Studio", "brand": "Brand", "design": "Design", "campaigns": "Campaigns", "production": "Production", "tech": "Tech", "xperience": "Xperience", "selected-work": "Selected Work"}, "projects": [{"id": "srnty", "name": "SRNTY", "category": "brand", "title": "Hospitality Brand Transformation and Architecture", "body": ["Serenity Hotels evolved into SRNTY through a complete hospitality brand transformation built around a quieter, more contemporary proposition: calm as a form of luxury. We at 3KG developed the strategic repositioning, business and brand architecture, SRNTY name evolution, portfolio naming system, verbal and visual identity, and a scalable framework connecting the group, destinations, properties and future ventures. We then translated the brand across content, film, digital communication, hotel applications, environments and the guest experience."], "meta": {"Client": "Serenity Hospitality Group", "Year": "2025 – ongoing", "Market": "Makadi · Sahl Hasheesh · Marsa Alam", "Scope": "Brand strategy · Brand architecture · Naming · Verbal identity · Visual identity · Content · Film · Digital communication · Website · Environmental branding"}, "images": [{"src": "assets/profile/srnty-goldenhour.webp", "alt": "SRNTY Hotels, golden-hour hero", "width": 1800, "height": 1013}, {"src": "assets/profile/srnty-p25.webp", "alt": "SRNTY brand hierarchy, Brand Story page 25", "width": 1800, "height": 1013}, {"src": "assets/profile/srnty-trifold.webp", "alt": "SRNTY Hotels trifold", "width": 1800, "height": 1200}, {"src": "assets/portfolio-refresh/srnty-1gSmVjQV.webp", "alt": "SRNTY visual direction and look and feel", "width": 1920, "height": 1240, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/srnty-1gunSV81.webp", "alt": "SRNTY hospitality brand book presentation", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/srnty-1SnzxKsj.webp", "alt": "SRNTY website and editorial presentation", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}], "sourceKeys": ["BRAND / SRNTY / A", "BRAND / SRNTY / B"], "storySections": [{"title": "Challenge", "paragraphs": ["Serenity Hospitality Group was preparing to expand across Makadi, Sahl Hasheesh – Red Sea and Marsa Alam – Red Sea, but its portfolio had grown without a clear hierarchy between the corporate group, consumer brand, destinations and individual properties.", "The greatest complexity was in Makadi, where three legacy hotel names and products needed to be reorganised into a clearer two-property structure under one destination brand. At the same time, the architecture needed to work for both multi-hotel and single-hotel destinations, resolve confusion created by the existing property names, preserve Serenity’s recognition and support future hotels, residential developments and lifestyle extensions.", "The challenge was not simply to redesign Serenity, but to replace a fragmented naming structure with a clear, scalable hospitality architecture that could unify the existing business without limiting its future growth."]}, {"title": "Solution", "paragraphs": ["We at 3KG began by separating the corporate and consumer-facing roles within the business. Serenity Hospitality Group remained the parent company, while SRNTY was established as its dedicated hospitality brand, distinct from the group’s other ventures.", "We then created a scalable hierarchy connecting the SRNTY masterbrand to its destinations, individual properties and future extensions. Within Makadi, the legacy portfolio was reorganised under SRNTY Makadi and resolved into two clearer property brands: SRNTY Sea Reef Makadi and SRNTY Sun Ray Makadi. Single-property destinations followed a simpler structure through SRNTY Sahl Hasheesh – Red Sea and SRNTY Marsa Alam – Red Sea, while Homes by SRNTY created a repeatable naming route for future residential expansion.", "This architecture formed the foundation for the SRNTY positioning, name evolution, verbal and visual identity, and its activation across content, film, digital communication, hotel applications, environments and guest touchpoints. Every expression reinforced the relationship between the group, hospitality brand, destination and property, creating one coherent system for the existing portfolio and future growth."]}, {"title": "Impact", "paragraphs": ["Through this work, we at 3KG gave Serenity Hospitality Group a clear structure for managing, communicating and expanding its hospitality portfolio. SRNTY now functions as the recognisable consumer-facing brand, while Serenity Hospitality Group retains its corporate role and legacy without competing with the hotel identity.", "The Makadi portfolio is organised into a clearer two-property system under a shared destination brand, while Sahl Hasheesh and Marsa Alam follow a consistent naming logic. The same architecture can accommodate future hotels, destinations and Homes by SRNTY developments without reinventing the brand structure each time.", "Beyond naming, the transformation created a shared foundation for identity, communication and the guest experience. This allows SRNTY to remain coherent across properties and touchpoints while giving the business the flexibility to expand into new hospitality and residential opportunities."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "aman", "name": "AMAN", "category": "brand", "title": "Fintech Brand Refresh and Bilingual Identity System", "body": ["AMAN, one of Egypt's pioneering digital financial services platforms, approached 3KG to redesign its English logo. We at 3KG recommended first refreshing the established Arabic mark so the bilingual identity could grow from the brand's strongest source of recognition."], "meta": {"Client": "AMAN Holding", "Market": "Egypt", "Scope": "Rebranding & bilingual identity · Arabic logo refresh · English logo design · Emblem design · Visual identity · Brand guidelines · Digital applications · Brand implementation"}, "images": [{"src": "assets/portfolio-refresh/aman-1UqPc9U_.webp", "alt": "AMAN reception identity application", "width": 1672, "height": 941, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/aman-1blbe1Rh.webp", "alt": "AMAN workspace identity application", "width": 1570, "height": 1002, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/aman-1DBPaLyX.webp", "alt": "AMAN merchant kiosk branding", "width": 1536, "height": 864, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/aman-1EXgZLgN.webp", "alt": "AMAN stationery envelope", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/aman-1e1P1yrr.webp", "alt": "AMAN campaign and app poster application", "width": 1672, "height": 941, "status": "Existing portfolio artwork"}], "sourceKeys": ["BRAND / AMAN / A", "BRAND / AMAN / B"]}, {"id": "nuxera", "name": "Nuxera", "category": "brand", "title": "Making Healthcare AI Clearer, More Human", "body": ["Healthcare AI can be difficult to understand before it can be trusted. Nuxera entered the market with technology spanning intelligent voice, medical data and clinical operations, and needed an identity that could make that proposition clear, credible and human. We at 3KG created the brand’s visual foundations and digital content system, building a distinctive language that connects technology, communication and care across identity, social media, graphic content and motion."], "meta": {"Year": "2025", "Market": "Riyadh, Saudi Arabia", "Scope": "Branding & positioning · Social media design · Graphic design · Motion graphics"}, "images": [{"src": "assets/portfolio-refresh/nuxera-1fWBD1PB.webp", "alt": "Nuxera wordmark and waveform identity", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/nuxera-18oAuS5i.webp", "alt": "Nuxera mobile brand application", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/nuxera-1x2bF78X.webp", "alt": "Nuxera clinical uniform branding", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/nuxera-1bDh2G4T.webp", "alt": "Nuxera tote bag application", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}], "sourceKeys": ["BRAND / Nuxera"], "storySections": [{"title": "Challenge", "paragraphs": ["Nuxera was entering a fast-developing healthcare AI category in the Arab market. Its proposition needed to speak to healthcare professionals, decision makers and wider audiences without reducing sophisticated technology to generic claims.", "Following conventional healthcare codes too closely could make the brand blend into the category. Leaning too heavily into technology risked making it feel cold, opaque or disconnected from the people behind care.", "The identity needed to hold clinical credibility and human accessibility together, while remaining flexible enough to support product education, corporate communication and future services."]}, {"title": "Solution", "paragraphs": ["We at 3KG built Nuxera’s visual identity around the connection between technology, communication and human interaction.", "At its core, a fluid waveform was integrated into the Nuxera wordmark, translating voice, data and intelligent exchange into a recognisable brand signature. Rounded typography softened the technical expression and helped the identity remain approachable.", "To move beyond the expected blue and green healthcare palette, we introduced a warm orange-to-pink gradient, supported by deep navy, white space and clear contrast. The direction gives Nuxera a more distinctive presence while retaining a calm, considered feel.", "We then extended the system through social media design, graphic communication and motion graphics, giving complex healthcare AI subjects a more engaging visual structure across platforms and formats."]}, {"title": "Impact", "paragraphs": ["3KG gave Nuxera a more ownable visual foundation for its entry into healthcare AI.", "The brand system creates a clear relationship between the mark, colour, typography and motion language, so product education, corporate messaging and digital content feel part of one recognisable presence.", "It continues to support Nuxera as it communicates a more specialised proposition around Saudi-built, Arabic-first healthcare AI and intelligent voice technology."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}, "motion": [{"src": "assets/portfolio-refresh/motion/nuxera.mp4", "poster": "assets/portfolio-refresh/motion/nuxera-poster.webp", "width": 1280, "height": 720, "title": "Nuxera identity film", "caption": "Nuxera identity film"}]}, {"id": "waffy", "name": "Waffy", "category": "brand", "title": "Loyalty with a Purpose", "body": ["We helped craft Waffy’s identity, starting with the name “Waffy,” meaning “loyal” in Arabic. Each package features the face of a rescued Baladi dog or cat. Through a QR code, customers can learn the animal’s story, track its care journey, and even visit its location."], "meta": {"Market": "Egypt", "Scope": "Naming · Branding concept & strategy · Packaging · POS campaign · Brand implementation"}, "images": [{"src": "assets/profile/waffy-1.webp", "alt": "Waffy — project artwork", "width": 900, "height": 281}, {"src": "assets/profile/waffy-2.webp", "alt": "Waffy — project artwork", "width": 728, "height": 318}, {"src": "assets/portfolio-refresh/waffy-1UA-0ywo.webp", "alt": "Waffy naming and mark sketches", "width": 1920, "height": 1439, "status": "Identity development sketch"}, {"src": "assets/portfolio-refresh/waffy-1A5gKgrS.webp", "alt": "Waffy early identity concept sketches", "width": 1920, "height": 1439, "status": "Identity development sketch"}], "sourceKeys": ["BRAND / Waffy"]}, {"id": "dlng", "name": "DLNG", "category": "brand", "title": "Turning Energy Infrastructure into an Iconic Brand", "body": ["Energy brands often need to communicate scale, trust and technical complexity through a simple visual mark. DLNG needed a brand identity that could stand out in a crowded LNG market while reflecting its role as a natural gas liquefaction plant based in Damietta, Egypt. We at 3KG developed a strategic logo design and visual identity system that connected industry symbolism, location, shareholder structure and future-facing energy communication into one recognisable brand expression."], "meta": {"Market": "Damietta, Egypt", "Scope": "Logo design · Visual identity · Brand book"}, "images": [{"src": "assets/portfolio-refresh/dlng-1idpwEgB.webp", "alt": "DLNG stationery identity", "width": 1440, "height": 960, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/dlng-1tp7ybos.webp", "alt": "DLNG branded transport application", "width": 1440, "height": 960, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/dlng-1D737Um1.webp", "alt": "DLNG building signage", "width": 850, "height": 567, "status": "Existing portfolio artwork"}], "sourceKeys": ["BRAND / DLNG"], "storySections": [{"title": "Challenge", "paragraphs": ["DLNG was operating in a highly specialised energy sector where many LNG companies share similar industrial cues, making differentiation difficult.", "The identity needed to feel credible within liquefied natural gas and energy infrastructure, but not generic. It also had to communicate several layers at once: the operational process of LNG production, the transformation of gas into liquid, the importance of Damietta as a strategic export location and the collaborative ownership behind the company.", "The challenge was to turn these technical and corporate details into a clear, iconic brand identity that could represent DLNG’s role in Egyptian LNG export while remaining simple enough to work across different brand applications."]}, {"title": "Solution", "paragraphs": ["We at 3KG built the DLNG logo around the relationship between energy, transformation and place.", "The mark combines a flame, representing LNG production, with a liquid drop that reflects the liquefaction process and the movement of gas into a transportable form. The letter “D” became a central visual anchor, connecting the brand directly to Damietta and its strategic position for export.", "The logo structure was also shaped to reflect DLNG’s shareholder composition, with three sections representing Eni, EGAS and EGPC. This allowed the visual identity to communicate partnership without becoming overly literal.", "For the colour system, we drew from the shareholders’ brand worlds while adding fresher, more vibrant tones to suggest progress and the future of energy. The angled orientation of the elements gave the mark a sense of movement and export direction, while the stable “D” maintained a feeling of reliability."]}, {"title": "Impact", "paragraphs": ["3KG gave DLNG a distinctive corporate brand identity that translates a complex energy operation into a clear visual symbol.", "The logo brings together industry relevance, geographic meaning, shareholder representation and energy transformation within one recognisable mark. This gives DLNG a stronger foundation for corporate communication, stakeholder presentations and brand applications across the LNG sector.", "The result is a strategic energy branding system that helps DLNG stand apart from conventional LNG identities while still communicating trust, scale and operational purpose."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "fasahet-somaya", "name": "Fasahet Somaya", "category": "brand", "title": "A branding and interior transformation", "body": ["Somaya El-Assiouty, a passionate and resilient entrepreneur. As the story goes, Fasahet Somaya's journey began in the heart of Downtown, where Somaya was working at Merette Publishing House. Faced with limited time for home-cooked meals, she turned to restaurants but realized the strain on her budget. The warmth and love she poured into her homemade dishes soon drew admiration from her co-workers, who encouraged her to turn her culinary talents into a business venture.", "Somaya's original small downtown eatery, affectionately named \"El-Fasaha,\" embodied the concept of a cozy family gathering space, reminiscent of her own modest abode. Over time, as the restaurant gained popularity, it naturally evolved into \"Fasahet Somaya.\" Six years into her entrepreneurial journey,", "Somaya decided it was time to expand, It was at this pivotal moment that 3KG, once devoted customers and passionate admirers of Somaya's talents, and friends stepped forward with an offer to breathe new life into this beloved venue."], "meta": {"Market": "Downtown Cairo, Egypt", "Scope": "Branding design & strategy · Interior & exterior facelift · Furniture concept · Social media"}, "images": [{"src": "assets/profile/fasahet-1.webp", "alt": "Fasahet Somaya — project artwork", "width": 900, "height": 505}, {"src": "assets/portfolio-refresh/fasahet-somaya-1EEm6q48.webp", "alt": "Fasahet Somaya restaurant facade in Downtown Cairo", "width": 1600, "height": 1200, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/fasahet-somaya-1MVbE-54.webp", "alt": "Somaya at the restaurant", "width": 590, "height": 350, "status": "Existing portfolio artwork"}], "sourceKeys": ["BRAND / Fasahet Somaya"], "storySections": [{"title": "Scope of work", "paragraphs": ["Brand Identity: 3KG went on a mission to capture the heart and soul of Somaya's culinary passion. The branding we crafted for Fasahet Somaya embodies the authenticity, warmth, and heritage that make it a beloved culinary destination.", "Interior Design: Our team meticulously designed the interior of Fasahet Somaya to reflect the essence of the Fas'ha – a gathering place where memories are made. Each element, from decor to furniture, was chosen to create a welcoming atmosphere that resonates with the restaurant's story.", "Culinary Tradition: Fasahet Somaya's commitment to homemade food aligns with the growing trend of appreciating authentic, quality cuisine in Egypt. We celebrated this tradition by crafting a brand and interior that pays homage to Somaya's dedication to serving delicious, home-cooked meals."]}, {"title": "Outcome", "paragraphs": ["3KG's collaboration with Fasahet Somaya has resulted in a branding and interior transformation that brings Somaya's remarkable journey to life. The restaurant stands as a testament to Somaya's strength, resilience, and the enduring appeal of homemade cuisine in Egypt. Located in the bustling heart of Downtown, Fasahet Somaya has become a beloved destination for locals from all walks of life, drawn by the promise of nourishing food and a welcoming atmosphere.", "Somaya's vision extends beyond profits; she treats her customers with the warmth and care of a mother, emphasizing that success is not just about business, but about the connections made over shared meals. As Somaya dreams of expanding her business further, 3KG is honored to have played a part in preserving the heart and heritage of Fasahet Somaya for all to enjoy."]}], "contentSource": {"title": "fasahet somaya sortlist content", "url": "https://docs.google.com/document/d/19fAWMLydq_yWnr75O-G4-fDu8I5rnFlwpw-1OgxSFUU/edit?usp=drivesdk", "id": "19fAWMLydq_yWnr75O-G4-fDu8I5rnFlwpw-1OgxSFUU", "modified": "2025-11-17T12:02:43.785Z"}}, {"id": "vodafone-egypt", "name": "Vodafone Egypt", "category": "design", "title": "Making Impact Easier to Understand", "body": ["A sustainability report should do more than hold information; it should help people understand impact. Vodafone Egypt’s 2025 Sustainability Report contained a large volume of corporate, environmental and social performance data, but needed a more accessible way to reach different audiences. We at 3KG developed a dedicated microsite that brought together the full Arabic and English reports, an executive summary and an animated digital version, turning corporate reporting into a clearer web design, UX design, report design and digital storytelling experience."], "meta": {"Year": "2025", "Market": "Egypt", "Scope": "Report design · Editorial system · Web / UX · Digital report experience", "Outputs": "Arabic + English reports · Executive summary · Animated version"}, "images": [{"src": "assets/profile/vf-p14.webp", "alt": "Vodafone Egypt Sustainability Report 2024–2025, Key Highlights page 14", "width": 1800, "height": 1013}, {"src": "assets/profile/vf-microsite.webp", "alt": "Vodafone Egypt sustainability report microsite, Arabic", "width": 1800, "height": 986}, {"src": "assets/portfolio-refresh/vodafone-19cIF1VQ.webp", "alt": "Vodafone 2025 sustainability reporting highlights", "width": 1920, "height": 1062, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/vodafone-1MQMd2z_.webp", "alt": "Vodafone sustainability reporting frameworks", "width": 1920, "height": 1061, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/vodafone-1j5TWRFJ.webp", "alt": "Vodafone executive-summary web experience", "width": 1920, "height": 1066, "status": "Existing portfolio artwork"}], "sourceKeys": ["DESIGN / Vodafone Egypt"], "storySections": [{"title": "Challenge", "paragraphs": ["Vodafone Egypt had an extensive Sustainability Report covering initiatives, achievements, performance data and environmental and social impact information. The depth was valuable, but presenting it only as one large corporate document made accessibility and engagement more difficult.", "Different stakeholders needed different ways into the content. Some required the complete report, while others needed a faster executive overview. The material also had to remain accessible for both Arabic- and English-speaking audiences.", "Simply designing another long PDF would organise the information, but not improve how people accessed, navigated or experienced it.", "The challenge was therefore to turn a complex sustainability report into a digital reporting experience that made the information easier to explore without reducing its accuracy, credibility or depth."]}, {"title": "Solution", "paragraphs": ["We at 3KG approached the Sustainability Report as a digital platform rather than a standalone corporate PDF.", "Through web design, web development, UX design and report design, we created a dedicated microsite that became the central destination for Vodafone’s sustainability communication. The platform organised the content into multiple formats, allowing each audience to choose the level of detail most relevant to them.", "The full report was made available in both English and Arabic, while the executive summary offered a faster route to the most important findings and sustainability performance highlights.", "To make the report more engaging, we translated the content into an animated digital experience. Motion design, visual hierarchy, information design and digital storytelling helped turn dense data and corporate content into a more approachable format."]}, {"title": "Impact", "paragraphs": ["3KG helped Vodafone Egypt move its Sustainability Report beyond the limits of a traditional corporate document.", "The microsite gave Vodafone one central platform for the full report, Arabic and English versions, executive summary and animated experience, making its sustainability communication easier to access, navigate and share.", "The project also created a stronger connection between corporate reporting and audience engagement. Stakeholders who needed detail could access the complete material, while wider audiences could explore the report through shorter, more visual formats.", "The result is a sustainability reporting experience built not only to document Vodafone’s work, but to help people better understand its environmental, social and corporate impact."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "alx", "name": "ALX", "category": "campaigns", "title": "Launch, Egypt + Morocco", "body": ["When ALX launched in Egypt and Morocco, they faced several challenges: the name was confused with “OLX”, the fully funded programmes were doubted, and the Mastercard logo was misunderstood. We developed a strategic launch plan to address these challenges.", "In June 2023, ALX Egypt encountered a significant hurdle: no budget was allocated for media buying for this cohort. We created a game called “ALX Superheroes” to motivate learners to share their ALX experiences on social media. Points were tracked over three months to maintain engagement."], "meta": {"Client": "ALX Arabia, part of ALX Africa", "Market": "Egypt · Morocco", "Scope": "Launch strategy · Localisation · Integrated campaigns · User-generated content · Offline activation · Digital content", "Year": "2023"}, "images": [{"src": "assets/portfolio-refresh/alx-1DW46l2s.webp", "alt": "ALX archive launch campaign portrait", "width": 1080, "height": 1080, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/alx-1_H8tmed.webp", "alt": "ALX archive virtual-assistant launch artwork", "width": 1080, "height": 1080, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/alx-1ixs3l7a.webp", "alt": "ALX archive application-deadline artwork, February 2022", "width": 1081, "height": 1081, "status": "Existing portfolio artwork"}], "sourceKeys": ["CAMPAIGNS / ALX / A", "CAMPAIGNS / ALX / B"]}, {"id": "novartis", "name": "Novartis", "category": "campaigns", "title": "Thalassemia Awareness Campaign", "body": [], "meta": {"Scope": "Creative concept · Key visuals · OOH implementation · Digital campaign strategy · Media planning & PR"}, "images": [{"src": "assets/portfolio-refresh/novartis-1AaVkTVL.webp", "alt": "Novartis thalassemia awareness billboard", "width": 1920, "height": 1440, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/novartis-1n4t2y7L.webp", "alt": "Novartis awareness campaign in a station", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/novartis-1M-hvoxo.webp", "alt": "Novartis thalassemia outdoor campaign", "width": 1920, "height": 1320, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/novartis-1ifx9yfN.webp", "alt": "Novartis campaign tote bag", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}], "sourceKeys": ["CAMPAIGNS / Novartis"]}, {"id": "tasaheel", "name": "Tasaheel", "category": "campaigns", "title": "Gold Campaign", "body": [], "meta": {"Scope": "Creative copy · Production · Post-production · Digital ad"}, "images": [{"src": "assets/portfolio-refresh/tasaheel-165_8a7G.webp", "alt": "Tasaheel Gold campaign — original film still 1", "width": 1920, "height": 1080, "status": "Existing recipe production artwork"}, {"src": "assets/portfolio-refresh/tasaheel-1gQELgo0.webp", "alt": "Tasaheel Gold campaign — original film still 2", "width": 1920, "height": 1080, "status": "Existing recipe production artwork"}, {"src": "assets/portfolio-refresh/tasaheel-1_p2DMh-.webp", "alt": "Tasaheel Gold campaign — original film still 3", "width": 1920, "height": 1080, "status": "Existing recipe production artwork"}, {"src": "assets/portfolio-refresh/tasaheel-1feaGWD7.webp", "alt": "Tasaheel Gold campaign — original film still 4", "width": 1920, "height": 1080, "status": "Existing recipe production artwork"}], "sourceKeys": ["CAMPAIGNS / Tasaheel"], "video": "https://drive.google.com/file/d/1DvZJpt4dXeVD_qhtmRUZ8HZrMj5FWs2p/view"}, {"id": "kipco", "name": "KIPCO", "category": "production", "title": "Corporate Film", "body": [], "meta": {"Shooting": "11 countries", "Scope": "Corporate video · Production"}, "images": [{"src": "assets/profile/kipco-skyline.webp", "alt": "KIPCO corporate video, Kuwait City skyline frame", "width": 1800, "height": 1013}], "sourceKeys": ["PRODUCTION / KIPCO"]}, {"id": "americana-recipes", "name": "Americana Recipes", "category": "production", "title": "Regional Recipe Development & Video Production", "body": ["Americana Foods commissioned a regional digital content programme built around 30 original recipes. We at 3KG developed the recipes and structured them into relevant content themes, including Ramadan, school lunchboxes, National Day specials for the UAE, Saudi Arabia and Oman, and quick recipes designed to be communicated in 30 seconds or less.", "We then translated the programme into a consistent short-form video series through food styling, video production, post-production and motion graphics, ready for regional publishing across digital platforms."], "meta": {"Year": "Dec 2024 – Ramadan 2025", "Scope": "Recipe development · Food styling · Video production · Post-production · Motion graphics", "Outputs": "30 recipe videos"}, "images": [{"src": "assets/profile/zinger_04.webp", "alt": "Air-fry lettuce wrap with zinger strips, recipe film frame", "width": 540, "height": 960}, {"src": "assets/profile/chicken_04.webp", "alt": "Air-fry lettuce wrap chicken burger, overhead preparation frame", "width": 540, "height": 960}, {"src": "assets/profile/buddha_02.webp", "alt": "Air-fry nuggets Buddha bowl, recipe film frame", "width": 540, "height": 960}], "sourceKeys": ["PRODUCTION / Americana Recipes"], "video": "https://drive.google.com/file/d/1NnZ_tTb3XQObcctzPzo6e5evZaNfgkpP/view", "storySections": [{"title": "Challenge", "paragraphs": ["Americana needed more than a collection of food videos. The brand required a repeatable regional content programme capable of turning its product range into relevant recipe ideas for different audiences, markets and calendar moments.", "Each recipe had to connect with a clear consumer occasion, from Ramadan and school lunchboxes to country-specific National Day content, while keeping the Americana product visible and naturally integrated into the story.", "Every complete recipe also had to be communicated in 30 seconds or less, competing within a fast-moving short-form content environment without sacrificing understanding, appetite appeal or product clarity. The videos needed to adapt across digital platforms while still feeling like one recognisable regional series."]}, {"title": "Solution", "paragraphs": ["We at 3KG developed 30 original recipes around Americana’s product portfolio, regional food preferences, consumer occasions and content calendar. The recipes were organised into focused themes, including Ramadan, school lunchboxes, National Day specials for the UAE, Saudi Arabia and Oman, and quick everyday recipe content.", "For production, we created a repeatable short-form storytelling structure. Each video opened with an immediate visual hook, introduced the product clearly, moved through the essential preparation moments and concluded with an appetising final dish reveal.", "Shot planning and food styling highlighted ingredients, textures and product cues. Editing maintained an energetic pace while preserving the clarity of each recipe, while post-production and motion graphics supported key information and prepared the content for publishing across platforms."]}, {"title": "Impact", "paragraphs": ["Americana gained a cohesive library of 30 original recipes and platform-ready short-form videos. The programme transformed the brand’s products into useful, appetising content connected to seasonal occasions, everyday consumer needs and market-specific cultural moments.", "By combining recipe development with production, the project also established a scalable regional content framework that Americana could use across markets, platforms and future content cycles."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "california-garden-recipes", "name": "California Garden Recipes", "category": "production", "title": "Regional Recipe Development & Video Production", "body": ["20 recipe videos developed for California Garden within the same regional recipe programme produced for Americana."], "meta": {"Year": "Dec 2024 – Ramadan 2025", "Scope": "Recipe development · Food styling · Video production · Post-production · Motion graphics", "Outputs": "20 recipe videos"}, "images": [{"src": "assets/portfolio-refresh/california-1ZOJ4Jnj.webp", "alt": "California Garden Ramadan recipe — molokhia with chicken and rice", "width": 1280, "height": 720, "status": "Existing recipe production artwork"}, {"src": "assets/portfolio-refresh/california-1FoWfEdE.webp", "alt": "California Garden Ramadan recipe — okra tray with chicken", "width": 1280, "height": 720, "status": "Existing recipe production artwork"}], "sourceKeys": ["PRODUCTION / California Garden Recipes"], "video": "https://drive.google.com/file/d/1jvtq2ANy2SdQGxIUXwM8kyicicU0LtoM/view?usp=drivesdk"}, {"id": "americana-foodservice", "name": "Americana Foodservice", "category": "tech", "title": "A Smarter Way to Explore Foodservice", "body": ["A large product portfolio only creates value when customers can understand what to do with it. Americana needed a smarter way to present its foodservice range across the UAE, Saudi Arabia and Kuwait, especially for QSR brands, restaurants, cafés and independent operators. We at 3KG designed and developed a bilingual digital catalogue that turned product discovery into a clearer B2B sales journey, combining market availability, specifications, recipes, usage inspiration and inquiry functionality in one platform."], "meta": {"Year · Market": "May – Aug 2025 · UAE, KSA, Kuwait", "Scope": "Web design · Web development · UX/UI · Digital catalogue"}, "images": [{"src": "assets/portfolio-refresh/americana-1XYW8Ioc.webp", "alt": "Americana Foodservice digital catalogue landing page", "width": 1920, "height": 959, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/americana-1GoKtt2a.webp", "alt": "Americana featured product selection", "width": 1920, "height": 1064, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/americana-13zEqOs5.webp", "alt": "Americana catalogue filters and product categories", "width": 1920, "height": 1036, "status": "Existing portfolio artwork"}], "sourceKeys": ["TECH / Americana Foodservice"], "storySections": [{"title": "Challenge", "paragraphs": ["Americana had an extensive foodservice portfolio and strong relationships with major QSR brands, but reaching a wider base of restaurants, cafés and independent foodservice businesses required a more accessible product-discovery experience.", "For many potential customers, a list of SKUs would not be enough. They needed to understand which products were relevant to their business, how each item could fit into a menu, what formats were available and how the offering changed across markets.", "The portfolio also carried practical complexity. Products covered multiple categories, pack sizes, specifications and availability rules across the UAE, Saudi Arabia and Kuwait.", "The challenge was therefore to turn a large product range into a simple, commercially useful digital catalogue that could support product discovery, menu inspiration, lead generation and B2B sales conversations."]}, {"title": "Solution", "paragraphs": ["We at 3KG approached the catalogue as a B2B digital sales platform, not a static online brochure.", "Through web design, web development, UX design and content structure, we created a bilingual platform where users could browse Americana’s portfolio by category and filter products according to market availability in the UAE, Saudi Arabia and Kuwait.", "Each product page was designed to support foodservice decision-making, including pack weight, configuration, shelf life, storage requirements, country of origin and key specifications.", "To move users from browsing to action, we integrated an inquiry-list function that allowed customers to select products of interest and begin a business conversation naturally.", "We also added recipes and product-use inspiration to show how Americana products could support menu development and new food offerings. This helped restaurants and cafés see not only what each product was, but how it could be used."]}, {"title": "Impact", "paragraphs": ["3KG gave Americana a scalable foodservice catalogue that supports B2B communication, product discovery and customer acquisition across three Gulf markets.", "The platform allows prospective customers to explore products independently, compare relevant options and identify solutions suited to their business before speaking to the sales team.", "It also makes Americana’s portfolio more useful for smaller restaurants and cafés. Product specifications support purchasing decisions, while recipes and usage inspiration help translate individual items into menu opportunities.", "The result is a market-specific digital sales tool that turns Americana’s large foodservice portfolio into a clearer journey from discovery to consideration and inquiry."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "americana-qsr", "name": "Americana QSR", "category": "xperience", "title": "Partner Gifting Activation", "body": ["A corporate gift can thank a partner, but a personalised experience can make the partnership visible. For Ramadan 2025, Americana wanted to gift its QSR partners a Ramadan basket. We at 3KG, saw an opportunity for a more memorable way for gifting. We developed a gifting activation built around custom 3D models, branded packaging and personalised product labels, turning a seasonal gesture into a shareable expression of partnership and business value."], "meta": {"Year": "Ramadan 2025", "Scope": "Creative concept · 3D model design · 3D printing"}, "images": [{"src": "assets/profile/mcd-diorama.webp", "alt": "McDonald's Americana diorama", "width": 1120, "height": 1400}, {"src": "assets/profile/americana-storefront.webp", "alt": "Americana storefront", "width": 1355, "height": 1359}, {"src": "assets/profile/bk-object.webp", "alt": "Burger King Americana object", "width": 789, "height": 907}, {"src": "assets/profile/gift-boxes.webp", "alt": "Americana Ramadan gift boxes", "width": 591, "height": 1280}, {"src": "assets/portfolio-refresh/americana-1XF8QSYo.webp", "alt": "Americana branded storefront model", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/americana-17vFU20k.webp", "alt": "Burger King partner gifting model", "width": 1600, "height": 1600, "status": "Existing portfolio artwork"}], "sourceKeys": ["XPERIENCE / Americana QSR"], "video": "https://drive.google.com/file/d/1-9n3aKFlvrM88hTCPiddTFljEsK0B8FL/view", "storySections": [{"title": "Challenge", "paragraphs": ["In the QSR and foodservice market, partnerships are built over time, but they are remembered through meaningful gestures.", "For Ramadan 2025, Americana initially needed a gifting basket for its existing QSR partners. The occasion was familiar, but the opportunity was bigger than a standard corporate gift. A ready-made basket could show appreciation, but it would not fully reflect the relationship Americana had built with each restaurant brand.", "The challenge was to make every partner feel individually recognised. The activation needed to carry the warmth of Ramadan, the relevance of brand personalisation and the strategic value of business development communication, without feeling like a conventional giveaway."]}, {"title": "Solution", "paragraphs": ["We at 3KG transformed the idea from a Ramadan basket into a personalised QSR brand experience.", "Each partner received a custom 3D model inspired by a recognisable element from its own brand identity. Instead of placing Americana at the centre of the gift, the concept placed the partner there, making the experience feel tailored, thoughtful and instantly familiar.", "The packaging continued the same story. Custom branded boxes, selected Ramadan treats and Americana products with individually designed labels turned the unboxing into a complete reveal moment, where every detail felt connected to the recipient.", "The activation was also designed to travel beyond the gift itself. Its visual appeal made it shareable, allowing Americana to celebrate its existing QSR partnerships publicly while showing future collaborators the level of creativity and attention it brings to every relationship."]}, {"title": "Impact", "paragraphs": ["3KG helped Americana turn a simple seasonal requirement into a distinctive QSR partner activation.", "The custom 3D models, personalised packaging and branded product labels gave each partner an experience built around its own identity, making the gift feel more like a tribute than a giveaway.", "The project also gave Americana a tangible way to express its partnership philosophy. Instead of saying it values collaboration, the activation showed it through design, detail and personalisation.", "Americana later shared the initiative as part of its QSR communication, extending its value beyond the Ramadan moment. What began as a partner gift became a relationship-building tool, a business development asset and a creative proof point for future foodservice collaborations."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "plastic-bank", "name": "Plastic Bank", "category": "xperience", "title": "Responsibility made physical.", "body": ["For Plastic Bank, recognizable plastic waste became the story inside resin coasters and recognition tiles. A useful object brought the message into everyday spaces. A display piece kept it visible. The result was a tangible starting point for a conversation about responsibility."], "meta": {"Market": "Egypt", "Scope": "Strategic gifting · Product design · Packaging · B2B campaign"}, "images": [{"src": "assets/portfolio-refresh/plastic-bank-r06-01_tile_square_1x1.webp", "alt": "Plastic Bank recognition tile with encapsulated plastic waste", "width": 1200, "height": 1200, "status": "R06 portfolio presentation using original product photography"}, {"src": "assets/portfolio-refresh/plastic-bank-r06-02_coasters_square_1x1.webp", "alt": "Plastic Bank handmade resin coaster pair", "width": 1200, "height": 1200, "status": "R06 portfolio presentation using original product photography"}, {"src": "assets/portfolio-refresh/plastic-bank-r06-03_pack_square_1x1.webp", "alt": "Plastic Bank kraft packaging and the two coaster designs", "width": 1200, "height": 1200, "status": "R06 portfolio presentation using original product photography"}], "sourceKeys": ["XPERIENCE / Plastic Bank"], "storySections": [{"title": "The brief", "paragraphs": ["We were presented with a brief from our client, Plastic Bank, to develop a truly unique giveaway product that would serve as a constant reminder of individual and corporate responsibility in addressing the plastic waste issue.", "Our target audience primarily consisted of corporate decision-makers, particularly those involved in the production of plastic-containing products, as well as influencers who have the power to promote the use of recycled plastic or influence others to reconsider their plastic consumption habits."]}, {"title": "The idea", "paragraphs": ["The main objective was to create a memorable item that would not only raise awareness about the plastic waste problem but also actively engage the target audience as consumers in finding a solution. It was crucial to use recyclable materials and design the product in a way that would encourage its retention as a persistent reminder of the issue.", "After careful consideration, we decided to craft resin coasters that encapsulated actual pieces of plastic waste that was collected by Plastic Bank collectors. This choice was deliberate, as it aimed to demonstrate how plastic persists for hundreds of years without decomposing. We carefully selected plastic waste from products that were familiar to the audience, including their own brand products, to emphasize that they were not only contributors to the problem but also potential contributors to the solution."]}], "contentSource": {"title": "Strategic gifting revival R06 + original product brief", "localPath": "/Users/iShabrawy/.codex/.chatgpt-projects/g-p-6a5a11fbb5a88191b14c7c1b6e7683c9/output/plastic-bank-campaign-2026-10-27/Landing_Page_Copy.txt", "originalBrief": "https://docs.google.com/document/d/1-lJ1Qmy4aSx2lpqS-ALJC3KE_GJ_NmLXN0it0oZCkC8/edit?usp=drivesdk"}, "motion": [{"src": "assets/portfolio-refresh/motion/plastic-bank.mp4", "poster": "assets/portfolio-refresh/motion/plastic-bank-poster.webp", "width": 1280, "height": 720, "title": "Plastic Bank — a small gift, a bigger conversation", "caption": "Portfolio film study · Reconstructed scenes with original product footage"}]}, {"id": "joy-scents", "name": "Joy Scents", "category": "selected-work", "title": "Giving Scent a Visual Language", "body": ["Scent is invisible, but a brand can still make it felt. Joy Scents needed a flexible visual identity that could express its growing fragrance portfolio across different moods, products and audiences. We at 3KG developed a brand identity and digital content system built around movement, atmosphere and variety, giving Joy a recognisable language across logo design, graphic design, social media design and motion-led communication."], "meta": {"Year": "2025 – ongoing", "Scope": "Branding · Logo animation · Social media design · Motion graphics"}, "images": [{"src": "assets/profile/joy-1.webp", "alt": "Joy Scents — project artwork", "width": 697, "height": 476}, {"src": "assets/portfolio-refresh/joy-v08-ultra_bronze.webp", "alt": "JOY Ultra — exterior product model study", "width": 900, "height": 1100, "status": "Work in progress — exterior product model study"}, {"src": "assets/portfolio-refresh/joy-v08-portable_black_copper_cap.webp", "alt": "JOY Portable — exterior product model study", "width": 900, "height": 1100, "status": "Work in progress — exterior product model study"}], "sourceKeys": ["SELECTED WORK / Joy Scents"], "storySections": [{"title": "Challenge", "paragraphs": ["Joy Scents needed stronger brand positioning and a more distinctive visual identity to stand out in a competitive fragrance and scenting market.", "Each scent had its own mood, ingredients and personality, so one fixed visual expression would not be enough. At the same time, giving every product a separate look could weaken the masterbrand.", "Joy also needed to speak to different audiences, from individual consumers to B2B customers scenting homes, stores, hotels, offices and commercial spaces. The identity had to feel expressive for lifestyle communication while remaining professional enough for corporate and commercial applications.", "The challenge was therefore to create a flexible brand system that could build recognition while allowing each scent and product family to feel distinct."]}, {"title": "Solution", "paragraphs": ["We at 3KG built Joy Scents around a flexible visual identity system inspired by the way fragrance moves through space.", "The logo was developed with multiple expressions connected to the scent experience. One variation used a botanical form to reference natural fragrance ingredients, while another extended the tail of the letter “J” into a candle-inspired shape, linking the brand to warmth, atmosphere and interior scenting.", "We expanded the identity through spirals and flowing graphic forms that could shift in scale, composition and application. This gave Joy a recognisable design language without forcing every product into the same visual treatment.", "Colour became a key tool for expressing variety. A diverse palette allowed different scent families to feel fresh, floral, warm, sweet, woody or more sophisticated while remaining connected to the masterbrand.", "Through brand strategy, visual identity, logo design, graphic design and digital content design, the system was created to work across packaging, product communication, social media, corporate messaging and motion graphics."]}, {"title": "Impact", "paragraphs": ["3KG gave Joy Scents a scalable fragrance brand identity that turned product variety into a visual strength.", "The new system allows individual scents and product families to carry their own character while staying connected through consistent logo principles, graphic forms, colour logic and design rules.", "It also gives Joy more flexibility across consumer and B2B communication. The same identity can support lifestyle content, product marketing, social media design, corporate presentations and motion-led storytelling without losing recognition.", "As Joy introduces new scents, product categories and commercial applications, they can grow within the existing brand system instead of requiring a new creative direction each time.", "The result is a clearer, more adaptable visual language that helps Joy Scents communicate atmosphere, variety and brand recognition through one coherent identity."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}}, {"id": "j-ra", "name": "Jēra", "category": "selected-work", "title": "A Brand Story Rooted in Harvest", "body": ["The name “Jera” draws inspiration from the Elder Futhark, where it symbolizes “harvest” and a “good year.” The combination of “JE” from Jermine and “RA” from Rasha in the brand’s name reinforces the personal connection between the co-founders and their creations."], "meta": {"Scope": "Naming & brand story · Branding design · Digital strategy · Content creation"}, "images": [{"src": "assets/portfolio-refresh/jera-v06-02_fibre_ensemble.webp", "alt": "Jēra furniture family — product presentation study", "width": 1600, "height": 1200, "status": "Work in progress — product presentation study"}, {"src": "assets/portfolio-refresh/jera-v06-01_suspended_curve.webp", "alt": "Jēra Cupcake — suspended product study", "width": 1280, "height": 1600, "status": "Work in progress — product presentation study"}, {"src": "assets/portfolio-refresh/jera-v06-03_fluted_architecture.webp", "alt": "Jēra Cupcake material and fluting detail", "width": 1280, "height": 1600, "status": "Work in progress — product presentation study"}, {"src": "assets/portfolio-refresh/jera-v06-04_ceramic_flight.webp", "alt": "Jēra ceramic bowl and plate study", "width": 1280, "height": 1600, "status": "Work in progress — product presentation study"}, {"src": "assets/portfolio-refresh/jera-v06-05_clay_ensemble.webp", "alt": "Jēra clay collection presentation study", "width": 1600, "height": 1200, "status": "Work in progress — product presentation study"}, {"src": "assets/portfolio-refresh/jera-v06-06_glaze_and_petals.webp", "alt": "Jēra glaze and petal detail", "width": 1280, "height": 1600, "status": "Work in progress — product presentation study"}, {"src": "assets/profile/jera-stationery.webp", "alt": "Jēra stationery system", "width": 1400, "height": 1400}, {"src": "assets/profile/jera-tags-1600.webp", "alt": "Jēra product hang tags", "width": 1400, "height": 1400}], "sourceKeys": ["SELECTED WORK / Jēra"], "storySections": [{"title": "Challenge", "paragraphs": ["In embarking on their creative journey, Rasha and Jermine encountered the challenge of introducing their unique line of handcrafted home, chalet, and office additions to a market already brimming with similar offerings. Their objective was clear: to create pieces that not only added aesthetic value but also fostered a personal connection, allowing users to place and engage with them in diverse ways. While this task appeared complex, they've skillfully transformed it into a reality."]}, {"title": "Solution", "paragraphs": ["The Jera brand marries the creative spirits of Rasha and Jermine, where beauty, versatility, and familiarity harmonize. Here are the key elements we considered during the branding process:", "Versatile Creations: Jera's products are designed to be versatile, allowing users to engage with them in unique ways and fit them seamlessly into their surroundings. This adaptability, while challenging to achieve, is at the heart of Jera's offerings.", "Earthy Aesthetic: Jera's creations are crafted from earthy, natural, or common materials and feature familiar colors. This deliberate choice gives Jera products a comforting and timeless quality, making them feel like old friends.", "Personal Connection: The combination of \"JE\" from Jermine and \"RA\" from Rasha in the brand's name reinforces the personal connection between the co-founders and their creations, emphasizing the human touch behind every piece.", "Historical Inspiration: The name \"Jera\" draws inspiration from the Elder Futhark, where it symbolizes \"harvest\" and a \"good year.\" This historical reference adds depth to the brand, hinting at abundance and fulfillment."]}], "contentSource": {"title": "jera sortlist description", "url": "https://docs.google.com/document/d/1MrbTFhsMM_AeFKwITTRiusSPBqbZze_Bh71NlnmVAKE/edit?usp=drivesdk", "id": "1MrbTFhsMM_AeFKwITTRiusSPBqbZze_Bh71NlnmVAKE", "modified": "2023-10-01T10:42:28.922Z"}, "motion": [{"src": "assets/portfolio-refresh/motion/j-ra.mp4", "poster": "assets/portfolio-refresh/motion/j-ra-poster.webp", "width": 1280, "height": 720, "title": "Jēra website presentation", "caption": "Jēra website presentation"}]}, {"id": "afied", "name": "AFIED", "category": "selected-work", "title": "Connecting Arab Industry to Global Markets", "body": [], "meta": {"Scope": "Naming · Branding concept & strategy · Concept development · Printing"}, "images": [{"src": "assets/profile/afied-building.webp", "alt": "AFIED building signage", "width": 1000, "height": 1000}, {"src": "assets/profile/afied-stationery-f095.webp", "alt": "AFIED stationery system", "width": 799, "height": 800}, {"src": "assets/profile/afied-container.webp", "alt": "Powered by AFIED shipping container", "width": 1000, "height": 1000}, {"src": "assets/portfolio-refresh/afied-1x-_HKJ3.webp", "alt": "AFIED billboard identity application", "width": 1000, "height": 1000, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/afied-1U80QC8j.webp", "alt": "AFIED branded shipping containers", "width": 1000, "height": 1000, "status": "Existing portfolio artwork"}], "sourceKeys": ["SELECTED WORK / AFIED"]}, {"id": "thirteen", "name": "Thirteen", "category": "selected-work", "title": "Brand voice, visuals and digital presence", "body": ["Thirteen came to us to bring their movement to life: a raw, rebellious, minimalist beauty philosophy that needed the right voice, visuals, and digital presence to match its message.", "We handled everything from brand storytelling to day-to-day execution, ensuring every touchpoint felt cohesive, intentional, and alive. From digital strategy, social content, and creative direction to full-scale photography, videography, influencer integration, and seasonal campaign rollouts, we built a brand experience rooted in clarity and conviction, both online and offline.", "We didn’t just manage the brand, we helped shape its voice, its visuals, and its value in the lives of its audience."], "meta": {"Scope": "Digital strategy · Photography · Videography · Creative direction · Website content"}, "images": [{"src": "assets/portfolio-refresh/thirteen-1FkmmNY-.webp", "alt": "Thirteen product and packaging photography", "width": 1268, "height": 714, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/thirteen-1HwqkAKf.webp", "alt": "Thirteen beauty-oil product photograph", "width": 1080, "height": 1080, "status": "Existing portfolio artwork"}, {"src": "assets/profile/thirteen-1.webp", "alt": "Thirteen — project artwork", "width": 354, "height": 706}], "sourceKeys": ["SELECTED WORK / Thirteen"], "storySections": [{"title": "Scope of work", "items": ["Full digital strategy and content planning (social media calendars, campaigns, community building)", "Editorial & product photography (elevated beauty shots, ingredient-focused imagery, UGC direction)", "Commercial and documentary-style videography (CEO’s journey, launching visuals)", "Creative direction & scriptwriting (for reels, campaigns, founder-led content, and masterclass materials)", "E-commerce strategy & website content (UX-aligned copy, product descriptions, campaign messaging)", "Influencer coordination and packaging rollout", "Campaigns across seasons and cultural moments"]}], "contentSource": {"title": "Thirteen Sortlist", "url": "https://docs.google.com/document/d/13NKQtXwkYJt2Rse5XzYpIKMKcshENeo0OaBTd4AO23c/edit?usp=drivesdk", "id": "13NKQtXwkYJt2Rse5XzYpIKMKcshENeo0OaBTd4AO23c", "modified": "2025-06-23T13:15:46.619Z"}, "motion": [{"src": "assets/portfolio-refresh/motion/thirteen.mp4", "poster": "assets/portfolio-refresh/motion/thirteen-poster.webp", "width": 1280, "height": 720, "title": "Thirteen website presentation", "caption": "Thirteen website presentation"}]}, {"id": "cccj-studio", "name": "CCCJ Studio", "category": "selected-work", "title": "Digital strategy and video", "body": ["When we partnered with CCCJ Studio, we encountered the challenge of transforming a niche jewelry art school in Egypt into a recognized and influential player on the international stage. CCCJ Studio's innovative approach to jewelry design education and collaboration with top-tier artists presented a unique value proposition, but we needed to convey this message effectively to a global audience."], "meta": {"Market": "Egypt", "Scope": "Content strategy · Social media · Video production"}, "images": [{"src": "assets/profile/cccj-1.webp", "alt": "CCCJ Studio — project artwork", "width": 899, "height": 492}], "sourceKeys": ["SELECTED WORK / CCCJ Studio"], "storySections": [{"title": "Solution", "paragraphs": ["To address this challenge, we developed a comprehensive digital strategy encompassing social media content, planning, and video production. Here's how we tackled the task:", "Content Strategy: We crafted a content plan that highlighted CCCJ Studio's holistic approach to jewelry education. We emphasized the fusion of design and technique, showcasing the vast array of materials and mediums used, allowing artists to freely experiment, and making choices aligned with their concepts. Our content emphasized how CCCJ Studio empowers artists to think outside the box, fostering creativity and innovation.", "Social Media Presence: We revamped CCCJ Studio's social media profiles to reflect its unique value proposition. This included creating visually appealing content that showcased students' work, featured collaborations with renowned artists, and highlighted the international exposure opportunities offered by CCCJ Studio.", "Video Production: Our team produced high-quality videos that captured the essence of CCCJ Studio's creative journey. These videos featured behind-the-scenes glimpses into jewelry-making processes, interviews with the artists, and success stories of students.", "Engagement Strategies: We implemented engagement strategies such as interactive posts, live sessions with artists, and contests to foster a sense of community among CCCJ Studio's followers. This helped build a loyal and engaged online audience.", "Analytics and Optimization: Regularly analyzing performance metrics allowed us to fine-tune our content and digital strategy, ensuring that CCCJ Studio's message resonated effectively with its target audience.", "By implementing this comprehensive digital strategy, We helped CCCJ Studio position itself as a pioneering force in jewelry art education not only in Egypt but on the international stage. Through captivating content and strategic outreach, CCCJ Studio now offers unique learning opportunities and international exposure to its students, revolutionizing jewelry design education."]}], "contentSource": {"title": "CCCJ Studio Sortlist", "url": "https://docs.google.com/document/d/18_9VRQ1AH3nH4X8FusoZNtxqowuRlTy2U0fosQQ1RAc/edit?usp=drivesdk", "id": "18_9VRQ1AH3nH4X8FusoZNtxqowuRlTy2U0fosQQ1RAc", "modified": "2023-10-02T12:15:29.335Z"}}, {"id": "t-d-designs", "name": "T&D Designs", "category": "selected-work", "title": "Building a Clearer B2B Presence", "body": ["Strong B2B businesses often lose value when their expertise is not easy to see. T&D Designs had years of experience, premium office furniture solutions and a growing project portfolio, but needed a clearer way to present its capabilities to clients and partners. We at 3KG developed a new website and company profile, creating a connected presentation system for its products, partnerships, portfolio and business development communication."], "meta": {"Market": "Cairo, Egypt", "Scope": "Website design · Company profile design"}, "images": [{"src": "assets/portfolio-refresh/t-d-1Baa-nFq.webp", "alt": "T&D Designs company profile cover", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/t-d-16s_oSxk.webp", "alt": "T&D office furniture catalogue spread", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/t-d-1Ea6UGhB.webp", "alt": "T&D Designs company profile interior pages", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}], "sourceKeys": ["SELECTED WORK / T&D Designs"], "storySections": [{"title": "Challenge", "paragraphs": ["T&D’s challenge was not the quality of its work, but the gap between its market experience and how that experience was presented.", "The company had a strong portfolio, international furniture partners and established expertise in the B2B office furniture sector, yet it lacked a comprehensive website and company profile that could bring this information together clearly.", "For potential clients, this created a communication gap. They needed to quickly understand who T&D was, what solutions it offered, which brands it represented and the scale of projects it could deliver. Without a central presentation system, much of the company’s credibility depended on direct sales conversations rather than being visible through the brand itself.", "The challenge was therefore to turn T&D’s products, capabilities and project work into a structured digital and corporate presentation experience that felt clear, professional and easy to navigate."]}, {"title": "Solution", "paragraphs": ["We at 3KG approached the website and company profile as two parts of one B2B communication system.", "We first organised T&D’s story into a clearer hierarchy, covering its background, office furniture solutions, international partners, capabilities and completed projects. This gave the brand a more structured way to communicate its value to clients, consultants and business partners.", "The company profile was designed as a focused business development tool. It gave the T&D team a professional format for introductions, credentials, meetings, pitches and client presentations.", "We then translated the same structure into the website, creating a digital platform where visitors could understand the company, explore its solutions and review its project portfolio with less friction.", "The visual direction placed furniture, workspaces and project photography at the centre of the experience. Instead of relying on excessive design elements, the system used clear layout, web design, portfolio design and content hierarchy to let T&D’s work communicate its scale and quality directly."]}, {"title": "Impact", "paragraphs": ["3KG gave T&D a stronger B2B brand presentation system that better reflects the business it had already built.", "The new website makes its office furniture solutions, capabilities and project portfolio easier to explore, while the company profile supports sales, pitches, client meetings and new business opportunities.", "The project also reduced the gap between T&D’s real market presence and its digital presence. Its value no longer depends only on being explained in conversation; it is now supported by clear tools that communicate credibility before the first meeting.", "The result is a more professional foundation for business development, helping T&D present its expertise, partnerships and portfolio with greater clarity across digital communication and client-facing touchpoints."]}], "contentSource": {"title": "SORTLIST CONTENT", "url": "https://docs.google.com/document/d/1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY/edit?usp=drivesdk", "id": "1KJYD1ExvQBMsKIFhK_5Lv-gvvXhf2LSPnjccB6OkPIY", "modified": "2026-09-17T13:39:15.259Z"}, "motion": [{"src": "assets/portfolio-refresh/motion/t-d-designs.mp4", "poster": "assets/portfolio-refresh/motion/t-d-designs-poster.webp", "width": 1280, "height": 720, "title": "T&D website presentation", "caption": "T&D website presentation"}]}, {"id": "monka", "name": "Monka", "category": "brand", "title": "Brand identity and digital presence", "body": ["Strategy, branding, digital and content work for a food and beverage brand."], "meta": {"Scope": "Strategy · Branding · Digital · Content"}, "images": [{"src": "assets/portfolio-refresh/monka-1-zN7vuE.webp", "alt": "Monka brand and product identity", "width": 1920, "height": 1440, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/monka-1zXSeukf.webp", "alt": "Monka packaging and digital brand applications", "width": 1920, "height": 1440, "status": "Existing portfolio artwork"}, {"src": "assets/portfolio-refresh/monka-1F8DEyoV.webp", "alt": "Monka online store presentation", "width": 1920, "height": 1280, "status": "Existing portfolio artwork"}], "sourceKeys": ["Prototype project P010", "Threekg portfolio / Monka / Sortlist"], "contentSource": {"localPath": "deliverables/3kg-website-review/prototype-project-records.json", "projectId": "P010", "status": "Source scope summary; expanded narrative not supplied"}, "motion": [{"src": "assets/portfolio-refresh/motion/monka.mp4", "poster": "assets/portfolio-refresh/motion/monka-poster.webp", "width": 1280, "height": 646, "title": "Monka online store presentation", "caption": "Monka online store presentation"}]}]};
